CREATE OR REPLACE FUNCTION public.configure_store_license(_mode text,_due timestamptz,_price numeric,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_row public.store_license; after_row public.store_license; BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_operators WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Acesso exclusivo FH Foods'; END IF; IF _mode IS NULL OR _mode NOT IN ('demonstration','active','suspended') OR _price IS NULL OR _price<=0 OR _price>100000 OR _reason IS NULL OR length(trim(_reason)) NOT BETWEEN 5 AND 500 OR (_mode='active' AND _due IS NULL) THEN RAISE EXCEPTION 'Licença inválida'; END IF; SELECT * INTO before_row FROM public.store_license WHERE id=1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Licença não inicializada'; END IF; UPDATE public.store_license SET mode=_mode,due_at=CASE WHEN _mode='active' THEN _due ELSE NULL END,monthly_price=round(_price,2),updated_at=now(),updated_by=auth.uid() WHERE id=1 RETURNING * INTO after_row; INSERT INTO public.license_audit(actor_id,previous_state,next_state,reason) VALUES(auth.uid(),to_jsonb(before_row),to_jsonb(after_row),trim(_reason)); END $$;
REVOKE ALL ON FUNCTION public.configure_store_license(text,timestamptz,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.configure_store_license(text,timestamptz,numeric,text) TO authenticated;